 83	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
 84	    ws: &Workspace<'_, R, D>,
 85	    selection: &ReleaseSelection,
 86	    source: SourceIdentity,
 87	) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
 88	    let mut components = Vec::new();
 89	    let mut component_kinds = BTreeSet::new();
 90	    let mut selected = BTreeMap::new();
 91	
 92	    for package in ws.graph.packages() {
 93	        for ecosystem in package
 94	            .canonical_manifests()
 95	            .map(|m| m.ecosystem())
 96	            .collect::<BTreeSet<_>>()
 97	        {
 98	            let id =
 99	                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
100	            if let Some(version) = selection.versions().get(&id) {
101	                selected.insert(id, (package, version.clone()));
102	            }
103	        }
104	    }
105	    for id in selection.versions().keys() {
106	        if !selected.contains_key(id) {
107	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
108	        }
109	    }
110	
111	    // These policies affect release selection/DAG policy. Store a digest only.
112	    push_component(
113	        &mut components,
114	        &mut component_kinds,
115	        "policy.cascade",
116	        format!("{:?}", ws.config.cascade),
117	    );
118	    push_component(
119	        &mut components,
120	        &mut component_kinds,
121	        "policy.validation",
122	        format!("{:?}", ws.config.validation),
123	    );
124	    push_component(
125	        &mut components,
126	        &mut component_kinds,
127	        "policy.groups",
128	        format!("{:?}", ws.config.groups),
129	    );
130	    for (key, registry) in &ws.config.registries {
131	        let binding = registry
132	            .url
133	            .as_deref()
134	            .map(|url| normalize_registry_url(key.as_str(), url))
135	            .transpose()?
136	            .unwrap_or_else(|| "default".to_string());
137	        push_component(
138	            &mut components,
139	            &mut component_kinds,
140	            format!("registry-binding:{}", key.as_str()),
141	            format!("{}:{binding}", registry.kind.prefix()),
142	        );
143	    }
144	
145	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
146	    for (id, (package, version)) in selected {
147	        let mut package_input = CanonicalTranscript::semantic_input_v1();
148	        package_input.push_str("package.id", &id.to_string());
149	        package_input.push_str("package.version", version.render());
150	        for manifest in &package.manifests {
151	            let bytes = std::fs::read(ws.root.join(&manifest.path)).map_err(|error| GraphError::ReleaseInputRead {
152	                path: manifest.path.clone(),
153	                message: error.to_string(),
154	            })?;
155	            package_input.push_str("manifest.path", &manifest.path.display().to_string());
156	            package_input.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
157	            package_input.push_str("manifest.role", &format!("{:?}", manifest.role));
158	            package_input.push_str("manifest.format", &format!("{:?}", manifest.format));
159	        }
160	        package_input.push_str("package.trigger", &format!("{:?}", package.release_trigger));
161	        package_input.push_str(
162	            "package.tag",
163	            &package
164	                .tag_template
165	                .as_ref()
166	                .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
167	        );
168	
169	        let mut publishes = Vec::new();
170	        let mut has_target = false;
171	        let mut has_forge_release = false;
172	        for target in &package.publish_to {
173	            match target {
174	                PublishTarget::None => {}
175	                PublishTarget::GitHubRelease => {
176	                    has_target = true;
177	                    has_forge_release = true;
178	                    package_input.push_str("package.target", "github-release");
179	                }
180	                _ => {
181	                    has_target = true;
182	                    package_input.push_str("package.target", &target_fingerprint(target)?);
183	                    if target.ecosystem() == Some(id.ecosystem()) {
184	                        if let Some(key) = target.registry_key() {
185	                            let operation = ReleaseOperation::registry_publish(
186	                                id.clone(),
187	                                version.clone(),
188	                                key.as_str().to_string(),
189	                                Vec::new(),
190	                            )
191	                            .map_err(|_error| GraphError::ReleaseIntentStale)?;
192	                            publishes.push(operation.id().clone());
193	                            operations.insert(operation.id().clone(), operation);
194	                        }
195	                    }
196	                }
197	            }
198	        }
199	        push_fingerprint(
200	            &mut components,
201	            &mut component_kinds,
202	            format!("package:{id}"),
203	            SemanticInputDigest::from_transcript(&package_input),
204	        );
205	        if has_target {
206	            publishes.sort();
207	            let tag = ReleaseOperation::tag(id.clone(), version.clone(), publishes)
208	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
209	            let tag_id = tag.id().clone();
210	            operations.insert(tag_id.clone(), tag);
211	            if has_forge_release {
212	                let forge = ReleaseOperation::forge_release(id, version, vec![tag_id])
213	                    .map_err(|_error| GraphError::ReleaseIntentStale)?;
214	                operations.insert(forge.id().clone(), forge);
215	            }
216	        }
217	    }
218	    Ok((
219	        ReleaseInputSnapshotV1::new(source, components),
220	        operations.into_values().collect(),
221	    ))
222	}
