267	fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
268	    let endpoint = |registry, value: Option<&String>| {
269	        value
270	            .map(|url| normalize_registry_url(registry, url))
271	            .transpose()
272	            .map(|value| value.unwrap_or_else(|| "default".to_string()))
273	    };
274	    match target {
275	        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
276	        PublishTarget::Npm { registry, access } => Ok(format!(
277	            ";target=npm:{}:{access:?}",
278	            endpoint("npm", registry.as_ref())?
279	        )),
280	        PublishTarget::Pypi { index } => Ok(format!(";target=pypi:{}", endpoint("pypi", index.as_ref())?)),
281	        PublishTarget::NuGet { source } => Ok(format!(";target=nuget:{}", endpoint("nuget", source.as_ref())?)),
282	        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
283	        PublishTarget::None => Ok(";target=none".to_string()),
284	        #[allow(unreachable_patterns)]
285	        _ => Ok(";target=future".to_string()),
286	    }
287	}
