289	/// Normalizes only scheme, authority (including explicit port), and path.
290	/// Userinfo, queries, and fragments are rejected before they can influence a
291	/// durable binding fingerprint.
292	fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
293	    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
294	        registry: registry.to_string(),
295	        reason: "missing scheme",
296	    })?;
297	    if scheme.is_empty() || remainder.is_empty() {
298	        return Err(GraphError::UnsafeRegistryBinding {
299	            registry: registry.to_string(),
300	            reason: "empty scheme or authority",
301	        });
302	    }
303	    if remainder.contains('@') {
304	        return Err(GraphError::UnsafeRegistryBinding {
305	            registry: registry.to_string(),
306	            reason: "userinfo is forbidden",
307	        });
308	    }
309	    if remainder.contains('?') {
310	        return Err(GraphError::UnsafeRegistryBinding {
311	            registry: registry.to_string(),
312	            reason: "query string is forbidden",
313	        });
314	    }
315	    if remainder.contains('#') {
316	        return Err(GraphError::UnsafeRegistryBinding {
317	            registry: registry.to_string(),
318	            reason: "fragment is forbidden",
319	        });
320	    }
321	    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
322	    if authority.is_empty() || authority.chars().any(char::is_whitespace) {
323	        return Err(GraphError::UnsafeRegistryBinding {
324	            registry: registry.to_string(),
325	            reason: "invalid authority",
326	        });
327	    }
328	    let suffix = if path.is_empty() {
329	        String::new()
330	    } else {
331	        format!("/{path}")
332	    };
333	    Ok(format!(
334	        "{}://{}{}",
335	        scheme.to_ascii_lowercase(),
336	        authority.to_ascii_lowercase(),
337	        suffix
338	    ))
339	}
